const number=span('function ankiNumericText(value)','function ankiNumericAudit(card','return {tokens,unsupported:[...new Set(unsupported)]}');
const N=new Function(number+';return ankiNumericTokens;')();
const source=Q.kbNormForMatch('The synthetic marker reads 600 units.');
const observed={numericPrefix:Q.kbQuoteInSource('The synthetic marker reads 60',source),legitimateCompleteTokenSubstring:Q.kbQuoteInSource('synthetic marker reads 600',source),unicodeMinus:N('−5 °C'),asciiMinus:N('-5 °C'),squared:N('5 cm²'),plain:N('5 cm')};
